<?php
namespace App\Support;
use App\Models\{User,PortalPrivacyState as State,PortalPrivacyNotice as Notice,PortalPrivacyAcknowledgement as Ack,PortalPrivacyCase as Review};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
class PortalPrivacy {
 public const CHECKS=['controller_contact','data_categories','purposes','lawful_bases','special_category','staff_monitoring','database_engine_provider','database_region','files_region','backup_region_retention','supplier_dpa_subprocessors_transfers','legacy_ionos_copies','retention_holds','rights_alternatives_review'];
 public static function event(User $u,string $event,string $key,array $data):void {DB::table('portal_privacy_events')->insert(['actor_id'=>$u->id,'event'=>$event,'subject_key'=>$key,'payload'=>Crypt::encryptString(json_encode($data,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function fields(State $s):array {return ['id'=>(int)$s->id,'revision'=>$s->revision,'current_notice_id'=>$s->current_notice_id,'enabled'=>$s->enabled];}
 public static function intact(State $s):bool {try{return $s->proof===self::fields($s);}catch(\Throwable){return false;}}
 private static function actor(User $u,int $auth,bool $manager=false):User {$u=User::whereKey($u->id)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->auth_version===$auth&&(!$manager||LearningAccess::manager($u)),403);return $u;}
 private static function state(?int $revision=null):State {$s=State::whereKey(1)->lockForUpdate()->firstOrFail();if(!self::intact($s)||$revision!==null&&$revision!==$s->revision){CentrePlanning::fail('Privacy controls changed or need recovery; reload the current version.');}return $s;}
 public static function current(?State $s=null):?Notice {try{$s??=State::find(1);if(!$s||!self::intact($s)||!$s->current_notice_id){return null;}$n=Notice::find($s->current_notice_id);return $n&&self::published($n)?$n:null;}catch(\Throwable){return null;}}
 public static function published(Notice $n):bool {try{return $n->state==='Published'&&ReviewedImports::hash($n->body)===$n->body_hash&&$n->publication['body_hash']===$n->body_hash&&$n->publication['notice_id']===$n->id;}catch(\Throwable){return false;}}
 public static function draft(User $actor,int $auth,string $label,string $text,string $contact,array $checks):Notice {return DB::transaction(function()use($actor,$auth,$label,$text,$contact,$checks):Notice {$u=self::actor($actor,$auth,true);$v=validator(['label'=>$label,'text'=>$text,'contact'=>$contact],['label'=>'required|string|max:100|unique:portal_privacy_notices,label','text'=>'required|string|min:200|max:50000','contact'=>'required|email|max:250'])->validate();$n=new Notice(['id'=>(string)Str::uuid(),'label'=>$v['label'],'created_by'=>$u->id,'state'=>'Draft']);$n->body=['label'=>$v['label'],'text'=>$v['text'],'contact'=>$v['contact'],'verification'=>$checks];$n->body_hash=ReviewedImports::hash($n->body);$n->save();self::event($u,'notice_drafted',$n->id,['body_hash'=>$n->body_hash]);return $n;},3);}
 public static function publish(User $actor,int $auth,Notice $record,int $revision):void {DB::transaction(function()use($actor,$auth,$record,$revision):void {$u=self::actor($actor,$auth,true);abort_unless($u->role==='ceo',403);$s=self::state($revision);$n=Notice::whereKey($record->id)->lockForUpdate()->firstOrFail();if($n->state!=='Draft'||ReviewedImports::hash($n->body)!==$n->body_hash){CentrePlanning::fail('Review an intact immutable draft.');}$refs=$n->body['verification']??[];foreach(self::CHECKS as$key){$ref=$refs[$key]??null;if(!is_string($ref)||mb_strlen(trim($ref))<5||mb_strlen($ref)>2000||preg_match('/\b(unknown|pending|tbd|tbc|unverified|placeholder)\b/i',$ref)){CentrePlanning::fail('Every hosting, purpose, contract, retention, rights and review reference must be verified before publication. Missing: '.$key);}}$n->state='Published';$n->publication=['notice_id'=>$n->id,'body_hash'=>$n->body_hash,'approved_by'=>$u->id,'at'=>now()->toIso8601String(),'verification_is_human_attestation'=>true];$n->save();$s->current_notice_id=$n->id;$s->revision++;$s->proof=self::fields($s);$s->save();self::event($u,'notice_published',$n->id,['revision'=>$s->revision,'body_hash'=>$n->body_hash,'enabled'=>$s->enabled]);},3);}
 public static function enable(User $actor,int $auth,int $revision,bool $enabled,string $reason):void {DB::transaction(function()use($actor,$auth,$revision,$enabled,$reason):void {$u=self::actor($actor,$auth,true);abort_unless($u->role==='ceo',403);$s=self::state($revision);if($enabled&&!self::current($s)||!filled($reason)||mb_strlen($reason)>2000){CentrePlanning::fail('Approve the verified notice before enabling, and record a safe rollout/recovery reason.');}$s->enabled=$enabled;$s->revision++;$s->proof=self::fields($s);$s->save();self::event($u,'gate_changed','state',['revision'=>$s->revision,'enabled'=>$enabled,'reason'=>$reason]);},3);}
 private static function seen(State $s,string $id,string $hash):Notice {$n=self::current($s);if(!$n||$n->id!==$id||$n->body_hash!==$hash){CentrePlanning::fail('The privacy notice changed; read the current version before deciding.');}return $n;}
 public static function caseFields(Review $c):array {return ['id'=>$c->id,'user_id'=>$c->user_id,'open_user_id'=>$c->open_user_id,'notice_id'=>$c->notice_id,'state'=>$c->state,'version'=>$c->version,'review_on'=>$c->review_on?->toDateString()];}
 public static function caseIntact(Review $c):bool {try{return $c->details['fields']===self::caseFields($c);}catch(\Throwable){return false;}}
 public static function open(User $u):?Review {return Review::where('open_user_id',$u->id)->first();}
 public static function alternative(Review $c,?Notice $n):bool {try{return self::caseIntact($c)&&$c->state==='Alternative'&&$c->review_on?->gte(today())&&$n&&$c->details['decision_notice']===$n->id&&$c->details['decision_hash']===$n->body_hash;}catch(\Throwable){return false;}}
 public static function acknowledged(User $u,Notice $n):bool {try{$a=Ack::where('user_id',$u->id)->where('notice_id',$n->id)->first();return $a&&$a->body_hash===$n->body_hash&&$a->proof['user_id']===$u->id&&$a->proof['notice_id']===$n->id&&$a->proof['body_hash']===$n->body_hash&&$a->proof['kind']==='acknowledgement';}catch(\Throwable){return false;}}
 public static function acknowledge(User $actor,int $auth,string $id,string $hash):void {DB::transaction(function()use($actor,$auth,$id,$hash):void {$u=self::actor($actor,$auth);$s=self::state();$n=self::seen($s,$id,$hash);if(self::open($u)){CentrePlanning::fail('Your concern needs a reviewed decision before acknowledgement.');}if(self::acknowledged($u,$n)){return;}$a=Ack::where('user_id',$u->id)->where('notice_id',$n->id)->first();if($a){CentrePlanning::fail('Acknowledgement proof needs recovery.');}Ack::create(['user_id'=>$u->id,'notice_id'=>$n->id,'body_hash'=>$n->body_hash,'acknowledged_at'=>now(),'proof'=>['user_id'=>$u->id,'notice_id'=>$n->id,'body_hash'=>$n->body_hash,'kind'=>'acknowledgement','at'=>now()->toIso8601String(),'consent_recorded'=>false]]);self::event($u,'notice_acknowledged',$n->id,['body_hash'=>$n->body_hash,'consent_recorded'=>false]);},3);}
 public static function concern(User $actor,int $auth,string $id,string $hash,string $token,string $text):Review {return DB::transaction(function()use($actor,$auth,$id,$hash,$token,$text):Review {$u=self::actor($actor,$auth);$s=self::state();$n=self::seen($s,$id,$hash);if(!Str::isUuid($token)||!filled($text)||mb_strlen($text)>2000){CentrePlanning::fail('Record a brief concern using a fresh form.');}$old=Review::where('request_token',$token)->first();if($old){abort_unless($old->user_id===$u->id,403);return $old;}if(self::open($u)){CentrePlanning::fail('Your existing concern is still under review; use its contact route.');}$c=new Review(['id'=>(string)Str::uuid(),'request_token'=>$token,'user_id'=>$u->id,'open_user_id'=>$u->id,'notice_id'=>$n->id,'state'=>'Open','version'=>1]);$c->details=['fields'=>self::caseFields($c),'concern'=>$text,'history'=>[]];$c->save();self::event($u,'concern_opened',$c->id,['notice_id'=>$n->id,'access'=>'protected interactive use paused; rights/contact/logout retained']);return $c;},3);}
 public static function decide(User $actor,int $auth,Review $record,int $version,string $action,?string $reviewOn,string $reason,bool $recovery=false):void {DB::transaction(function()use($actor,$auth,$record,$version,$action,$reviewOn,$reason,$recovery):void {$u=self::actor($actor,$auth,true);$s=self::state();$c=Review::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!self::caseIntact($c)||$c->version!==$version||$c->open_user_id!==$c->user_id||!in_array($action,['Resolved','Alternative','Archive-review','Deletion-review'],true)||!filled($reason)||mb_strlen($reason)>2000){CentrePlanning::fail('Use a current open review and a safe decision reason.');}if($u->id===$c->user_id){$last=User::where('active',true)->whereIn('role',['admin','ceo'])->count()===1;abort_unless($action==='Alternative'&&$recovery&&($u->role==='ceo'||$last),403);}if($action==='Alternative'){validator(['review_on'=>$reviewOn],['review_on'=>'required|date_format:Y-m-d|after:today'])->validate();if(!self::current($s)){CentrePlanning::fail('A current approved notice is required for reviewed alternative access.');}}$before=self::caseFields($c);$d=$c->details;$c->version++;$c->state=$action;$c->review_on=$action==='Alternative'?$reviewOn:null;$c->open_user_id=$action==='Resolved'?null:$c->user_id;$d['history'][]=['before'=>$before,'by'=>$u->id,'reason'=>$reason,'action'=>$action,'at'=>now()->toIso8601String(),'emergency_recovery'=>$recovery];$d['fields']=self::caseFields($c);$d['decision_notice']=$s->current_notice_id;$d['decision_hash']=self::current($s)?->body_hash;$c->details=$d;$c->save();self::event($u,'concern_reviewed',$c->id,['before'=>$before,'after'=>self::caseFields($c),'reason'=>$reason,'emergency_recovery'=>$recovery,'no_acknowledgement_fabricated'=>true,'account_deleted'=>false]);},3);}
}
